BEGIN READ ONLY;
WITH minted AS(SELECT payload->>'tokenId' token_id,sum((payload->>'amount')::numeric) minted FROM proof_indexer.events WHERE kind='token-mint' AND status='confirmed' AND valid GROUP BY 1),held AS(SELECT token_id,sum(confirmed_balance) held FROM proof_indexer.credit_balances GROUP BY 1) SELECT count(*) definitions,count(*) FILTER(WHERE coalesce(m.minted,0)*CASE WHEN d.metadata->>'amountStorageModel'='work-subatoms-v2' THEN 10000000000000000 ELSE 1 END!=coalesce(h.held,0)) conservation_errors,count(*) FILTER(WHERE d.max_supply>0 AND coalesce(m.minted,0)>d.max_supply/CASE WHEN d.metadata->>'amountStorageModel'='work-subatoms-v2' THEN 10000000000000000 ELSE 1 END) cap_errors FROM proof_indexer.credit_definitions d LEFT JOIN minted m USING(token_id) LEFT JOIN held h USING(token_id) WHERE d.ticker NOT IN ('POWB','INCB');
ROLLBACK;

\set ON_ERROR_STOP on
BEGIN READ ONLY;
SET LOCAL statement_timeout='15s';
SET LOCAL lock_timeout='2s';
SELECT json_build_object('txid',t.txid,'status',t.status,'height',t.block_height,'hash',t.block_hash,'index',t.block_index,'outputs',json_agg(json_build_object('vout',o.vout,'scriptpubkey',o.scriptpubkey) ORDER BY o.vout)) FROM proof_indexer.transactions t JOIN proof_indexer.tx_outputs o USING(network,txid) WHERE t.network='livenet' AND t.status='confirmed' AND o.scriptpubkey LIKE '6a%' GROUP BY t.network,t.txid ORDER BY t.block_height,t.block_index,t.txid;
ROLLBACK;

import base64,collections,datetime,hashlib,json,os,pathlib,subprocess,time,urllib.request
def sql(query):
    p=subprocess.run(['runuser','-u','postgres','--','env','PGOPTIONS=-c default_transaction_read_only=on -c statement_timeout=15000 -c lock_timeout=2000','psql','-XAt','-v','ON_ERROR_STOP=1','-d','proof_indexer'],input='SELECT coalesce(json_agg(q),\'[]\') FROM ('+query+') q;',text=True,capture_output=True,timeout=25)
    if p.returncode: raise RuntimeError(p.stderr[:1000])
    return json.loads(p.stdout)
pid=subprocess.check_output(['systemctl','show','proofofwork-api','-p','MainPID','--value'],text=True).strip()
env=dict(x.split(b'=',1) for x in pathlib.Path('/proc/'+pid+'/environ').read_bytes().split(b'\0') if b'=' in x)
rpcurl=env[b'BITCOIN_RPC_URL'].decode()
assert urllib.parse.urlsplit(rpcurl).hostname in ['127.0.0.1','localhost']
auth=base64.b64encode(env[b'BITCOIN_RPC_USER']+b':'+env[b'BITCOIN_RPC_PASSWORD']).decode()
def rpcbatch(calls):
    body=[{'jsonrpc':'2.0','id':i,'method':m,'params':p} for i,(m,p) in enumerate(calls)]
    req=urllib.request.Request(rpcurl,data=json.dumps(body).encode(),headers={'Content-Type':'application/json','Authorization':'Basic '+auth})
    with urllib.request.urlopen(req,timeout=30) as r: res=json.load(r,parse_float=str)
    results={x['id']:x for x in res}
    assert len(results)==len(calls)
    return [results[i] for i in range(len(calls))]
def rpc(method,params=[]):
    r=rpcbatch([(method,params)])[0]
    if r.get('error'): raise RuntimeError(str(r['error']))
    return r['result']
out={'startedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'scope':'all stored confirmed transaction raw bytes and normalized detail rows'}
out['coreBefore']=rpc('getblockchaininfo')
rows=sql("SELECT txid,block_height,block_hash,block_index,raw_tx->>'hex' hex FROM proof_indexer.transactions WHERE network='livenet' AND status='confirmed' ORDER BY block_height,block_index,txid")
out['count']=len(rows);out['rawMismatches']=[];out['rpcFailures']=[]
core={}
for start in range(0,len(rows),16):
 batch=rows[start:start+16]
 for b,r in zip(batch,rpcbatch([('getrawtransaction',[b['txid'],1,b['block_hash']]) for b in batch])):
  if r.get('error'): out['rpcFailures'].append({'txid':b['txid'],'error':r['error']});continue
  c=r['result'];core[b['txid']]=c
  if c['hex']!=b['hex'] or c['txid']!=b['txid'] or c.get('blockhash')!=b['block_hash'] or c.get('confirmations',0)<1: out['rawMismatches'].append(b['txid'])
 if start%2048==0: print(json.dumps({'progress':'core-raw-bytes','checked':start+len(batch)}),flush=True)
outs=sql("SELECT o.txid,o.vout,o.value_sats,o.scriptpubkey FROM proof_indexer.tx_outputs o JOIN proof_indexer.transactions t USING(network,txid) WHERE t.status='confirmed' AND t.network='livenet' ORDER BY o.txid,o.vout")
from decimal import Decimal
