\set ON_ERROR_STOP on
\pset pager off
BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL statement_timeout='30s';
SET LOCAL lock_timeout='5s';
SELECT status,count(*) FROM proof_indexer.transactions GROUP BY status;
SELECT protocol,status,valid,count(*),sum(amount_sats) FROM proof_indexer.events GROUP BY 1,2,3 ORDER BY 1,2,3;
SELECT 'duplicate-event-key' test,count(*) FROM (SELECT network,event_key FROM proof_indexer.events GROUP BY 1,2 HAVING count(*)>1) q
UNION ALL SELECT 'duplicate-position',count(*) FROM (SELECT network,txid,op_return_vout,record_ordinal FROM proof_indexer.events WHERE status='confirmed' GROUP BY 1,2,3,4 HAVING count(*)>1) q
UNION ALL SELECT 'event-orphan',count(*) FROM proof_indexer.events e LEFT JOIN proof_indexer.transactions t USING(network,txid) WHERE t.txid IS NULL
UNION ALL SELECT 'event-parent-status',count(*) FROM proof_indexer.events e JOIN proof_indexer.transactions t USING(network,txid) WHERE e.status IS DISTINCT FROM t.status
UNION ALL SELECT 'confirmed-block-missing',count(*) FROM proof_indexer.transactions t LEFT JOIN proof_indexer.blocks b ON b.network=t.network AND b.block_hash=t.block_hash AND b.height=t.block_height AND b.canonical WHERE t.status='confirmed' AND b.block_hash IS NULL
UNION ALL SELECT 'confirmed-scan-marker-missing',count(*) FROM proof_indexer.transactions WHERE status='confirmed' AND (raw_tx->'canonicalBlockScan'->>'blockHash' IS DISTINCT FROM block_hash OR raw_tx->'canonicalBlockScan'->>'height' IS DISTINCT FROM block_height::text)
UNION ALL SELECT 'confirmed-event-position-missing',count(*) FROM proof_indexer.events WHERE status='confirmed' AND (block_index IS NULL OR op_return_vout IS NULL OR record_ordinal IS NULL OR block_height IS NULL)
UNION ALL SELECT 'confirmed-event-parent-position',count(*) FROM proof_indexer.events e JOIN proof_indexer.transactions t USING(network,txid) WHERE e.status='confirmed' AND (e.block_height IS DISTINCT FROM t.block_height OR e.block_index IS DISTINCT FROM t.block_index OR e.block_time IS DISTINCT FROM t.block_time)
UNION ALL SELECT 'nonconfirmed-block-metadata',count(*) FROM proof_indexer.transactions WHERE status!='confirmed' AND (block_height IS NOT NULL OR block_hash IS NOT NULL OR block_index IS NOT NULL OR confirmed_at IS NOT NULL)
UNION ALL SELECT 'participant-orphan',count(*) FROM proof_indexer.event_participants p LEFT JOIN proof_indexer.events e USING(event_id) WHERE e.event_id IS NULL
UNION ALL SELECT 'ref-orphan',count(*) FROM proof_indexer.event_refs p LEFT JOIN proof_indexer.events e USING(event_id) WHERE e.event_id IS NULL
UNION ALL SELECT 'mail-orphan',count(*) FROM proof_indexer.mail_items m LEFT JOIN proof_indexer.transactions t USING(network,txid) WHERE t.txid IS NULL
UNION ALL SELECT 'mail-parent-status',count(*) FROM proof_indexer.mail_items m JOIN proof_indexer.transactions t USING(network,txid) WHERE m.status IS DISTINCT FROM t.status;
SELECT d.ticker,d.token_id,d.max_supply::text,d.mint_amount::text,d.metadata->>'amountStorageModel' units,sum(b.confirmed_balance)::text supply,count(b.address) holders,sum(b.pending_delta)::text pending FROM proof_indexer.credit_definitions d LEFT JOIN proof_indexer.credit_balances b USING(network,token_id) WHERE d.ticker IN ('WORK','POWB','INCB') GROUP BY 1,2,3,4,5;
SELECT 'invalid-credit-numeric' test,count(*) FROM proof_indexer.credit_balances WHERE confirmed_balance<0 OR confirmed_balance!=trunc(confirmed_balance) OR confirmed_balance::text IN ('NaN','Infinity','-Infinity') OR pending_delta!=trunc(pending_delta)
UNION ALL SELECT 'credit-without-definition',count(*) FROM proof_indexer.credit_balances b LEFT JOIN proof_indexer.credit_definitions d USING(network,token_id) WHERE d.token_id IS NULL;
WITH ordered AS (SELECT *,lag(block_height) OVER (PARTITION BY network ORDER BY block_height) h,lag(block_hash) OVER (PARTITION BY network ORDER BY block_height) hash,lag(closing_state_sha256) OVER (PARTITION BY network ORDER BY block_height) commitment,lag(closing_network_value_q8) OVER (PARTITION BY network ORDER BY block_height) n FROM proof_indexer.work_amo_block_transitions WHERE network='livenet') SELECT count(*) rows,min(block_height),max(block_height),count(*) FILTER(WHERE h IS NOT NULL AND (block_height!=h+1 OR previous_block_hash!=hash)) linkage_errors,count(*) FILTER(WHERE h IS NOT NULL AND opening_state_sha256!=commitment) opening_commitment_changes,count(*) FILTER(WHERE h IS NOT NULL AND opening_network_value_q8!=n) opening_value_errors,count(*) FILTER(WHERE NOT complete OR NOT block_atomic OR NOT fee_once OR NOT invalid_zero) incomplete,count(*) FILTER(WHERE closing_network_value_q8<opening_network_value_q8) value_decreases FROM ordered;
SELECT block_height,block_hash,model,closing_network_value_q8::text,fee_once,invalid_zero,complete FROM proof_indexer.work_amo_block_transitions ORDER BY block_height DESC LIMIT 2;
SELECT 'invalid-index' test,count(*) FROM pg_index WHERE NOT indisvalid OR NOT indisready UNION ALL SELECT 'unvalidated-constraint',count(*) FROM pg_constraint WHERE NOT convalidated;
SELECT name,setting FROM pg_settings WHERE name IN ('data_checksums','temp_file_limit','shared_buffers','work_mem','max_wal_size','max_slot_wal_keep_size','max_connections');
SELECT datname,pg_database_size(oid) FROM pg_database WHERE datallowconn ORDER BY 2 DESC;
SELECT n.nspname,c.relname,pg_total_relation_size(c.oid) bytes,c.reltuples::bigint estimated_rows,s.n_live_tup,s.n_dead_tup,s.last_autovacuum,s.last_autoanalyze FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_stat_user_tables s ON s.relid=c.oid WHERE n.nspname='proof_indexer' AND c.relkind='r' ORDER BY bytes DESC LIMIT 15;
SELECT spcname,pg_tablespace_location(oid),pg_tablespace_size(oid) FROM pg_tablespace;
SELECT datname,xact_commit,xact_rollback,conflicts,temp_files,temp_bytes,deadlocks,stats_reset FROM pg_stat_database WHERE datname='proof_indexer';
SELECT state,wait_event_type,count(*) sessions,max(extract(epoch FROM (now()-query_start))) longest_seconds FROM pg_stat_activity WHERE datname='proof_indexer' GROUP BY 1,2;
SELECT application_name,slot_name,active,pg_wal_lsn_diff(pg_current_wal_lsn(),restart_lsn) retained_bytes FROM pg_replication_slots LEFT JOIN pg_stat_replication ON active_pid=pid;
ROLLBACK;
\set ON_ERROR_STOP on
SET statement_timeout='30s';
SET lock_timeout='5s';
BEGIN READ ONLY;
WITH minted AS(SELECT payload->>'tokenId' token_id,sum((payload->>'amount')::numeric) minted FROM proof_indexer.events WHERE kind='token-mint' AND status='confirmed' AND valid GROUP BY 1),held AS(SELECT token_id,sum(confirmed_balance) held FROM proof_indexer.credit_balances GROUP BY 1) SELECT count(*) definitions,count(*) FILTER(WHERE coalesce(m.minted,0)*CASE WHEN d.metadata->>'amountStorageModel'='work-subatoms-v2' THEN 10000000000000000 ELSE 1 END!=coalesce(h.held,0)) conservation_errors,count(*) FILTER(WHERE d.max_supply>0 AND coalesce(m.minted,0)>d.max_supply/CASE WHEN d.metadata->>'amountStorageModel'='work-subatoms-v2' THEN 10000000000000000 ELSE 1 END) cap_errors FROM proof_indexer.credit_definitions d LEFT JOIN minted m USING(token_id) LEFT JOIN held h USING(token_id) WHERE d.ticker NOT IN ('POWB','INCB');
ROLLBACK;

