\set ON_ERROR_STOP on
BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL statement_timeout='30s';
SET LOCAL lock_timeout='5s';
SELECT jsonb_build_object('kind','confirmed-set','rows',count(*),'txidSetSha256',encode(sha256(convert_to(string_agg(txid,E'\n' ORDER BY txid),'UTF8')),'hex'),'maxConfirmedHeight',max(block_height),'confirmedAfterFirstCensus',count(*) FILTER(WHERE block_height>969387)) FROM proof_indexer.transactions WHERE network='livenet' AND status='confirmed';
