import urllib.request,json,datetime,time,sys
from pathlib import Path
hosts=['proofofwork.me','id.proofofwork.me','dns.proofofwork.me','desktop.proofofwork.me','browser.proofofwork.me','boost.proofofwork.me','amo.proofofwork.me','credit.proofofwork.me','wallet.proofofwork.me','work.proofofwork.me','infinity.proofofwork.me','inception.proofofwork.me','log.proofofwork.me','growth.proofofwork.me'] if len(sys.argv)<2 else [sys.argv[1]]
rows=[]
for host in hosts:
 start=time.monotonic();row={'host':host,'observedAtUtc':datetime.datetime.now(datetime.timezone.utc).isoformat()}
 try:
  with urllib.request.urlopen(urllib.request.Request('https://'+host+'/',headers={'User-Agent':'ProofOfWork read-only second-audit header check'}),timeout=15) as r:
   row.update({'status':r.status,'finalUrl':r.url,'headers':{k:r.headers.get(k) for k in ['Content-Security-Policy','Strict-Transport-Security','X-Content-Type-Options','Referrer-Policy','Permissions-Policy','X-Frame-Options','Cache-Control','Content-Type']}});r.read(256)
 except Exception as e:row['error']=str(e)
 row['elapsedMs']=round((time.monotonic()-start)*1000);rows.append(row)
Path('/tmp/pow-audit29-second/headers-'+('computer' if len(hosts)==1 else 'first14')+'.json').write_text(json.dumps(rows,indent=2)+'\n');print(json.dumps({'checked':len(rows),'errors':sum('error'in x for x in rows)}))
